import { getAdminSession } from "./adminAuth";
import { aborter } from "./aborter";

const BASE_URL =
  process.env.REACT_APP_CASTIA_WORKER_URL ||
  "https://castia-worker.lektodesigns.workers.dev";
const TIMEOUT_MS = 12000;

async function adminFetch(path, { method = "GET", body, signal } = {}) {
  const session = await getAdminSession();
  if (!session?.access_token) {
    const error = new Error("Your admin session has expired. Sign in again.");
    error.status = 401;
    throw error;
  }

  const combined = aborter(TIMEOUT_MS, signal);
  try {
    const response = await fetch(`${BASE_URL}${path}`, {
      method,
      signal: combined.signal,
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${session.access_token}`,
        ...(body ? { "Content-Type": "application/json" } : {}),
      },
      ...(body ? { body: JSON.stringify(body) } : {}),
    });
    let payload = null;
    try { payload = await response.json(); } catch { /* normalized below */ }
    if (!response.ok) {
      const error = new Error(payload?.error || payload?.message || `Request failed (${response.status})`);
      error.status = response.status;
      error.body = payload;
      throw error;
    }
    return payload;
  } finally {
    combined.cleanup();
  }
}

async function adminBinaryFetch(path, bytes, { signal } = {}) {
  const session = await getAdminSession();
  if (!session?.access_token) throw new Error("Your admin session has expired. Sign in again.");
  const combined = aborter(45000, signal);
  try {
    const response = await fetch(`${BASE_URL}${path}`, {
      method: "PUT", signal: combined.signal, body: bytes,
      headers: { Accept: "application/json", Authorization: `Bearer ${session.access_token}`, "Content-Type": "image/png" },
    });
    let payload = null;
    try { payload = await response.json(); } catch { /* normalized below */ }
    if (!response.ok) {
      const error = new Error(payload?.error || `Upload failed (${response.status})`);
      error.status = response.status;
      throw error;
    }
    return payload;
  } finally { combined.cleanup(); }
}

async function adminImageFetch(path, { signal } = {}) {
  const session = await getAdminSession();
  if (!session?.access_token) throw new Error("Your admin session has expired. Sign in again.");
  const combined = aborter(TIMEOUT_MS, signal);
  try {
    const response = await fetch(`${BASE_URL}${path}`, {
      method: "GET",
      signal: combined.signal,
      headers: { Accept: "image/png", Authorization: `Bearer ${session.access_token}` },
    });
    if (!response.ok) {
      let payload = null;
      try { payload = await response.json(); } catch { /* normalized below */ }
      const error = new Error(payload?.error || `Preview failed (${response.status})`);
      error.status = response.status;
      throw error;
    }
    return response.blob();
  } finally { combined.cleanup(); }
}

const requestId = () => crypto.randomUUID();

export const fetchAdminDashboard = (options) => adminFetch("/admin/shop-areas", options);
export const fetchAdminAccess = (options) => adminFetch("/admin/session", options);
export const fetchAdminShopMaps = (options) => adminFetch("/admin/shop-maps", options);

export const createShopMapDraft = (manifest) => adminFetch("/admin/shop-maps", {
  method: "POST", body: { manifest },
});
export const uploadShopMapTile = (draftId, filename, bytes, options) =>
  adminBinaryFetch(`/admin/shop-maps/${draftId}/tiles/${encodeURIComponent(filename)}`, bytes, options);
export const fetchShopMapPreviewTile = (versionId, filename, options) =>
  adminImageFetch(`/admin/shop-maps/${versionId}/tiles/${encodeURIComponent(filename)}`, options);
export const finalizeShopMap = (draftId) => adminFetch(`/admin/shop-maps/${draftId}/finalize`, { method: "POST" });
export const publishShopMap = (versionId) => adminFetch(`/admin/shop-maps/${versionId}/publish`, {
  method: "POST", body: { requestId: requestId() },
});
export const rollbackShopMap = (versionId) => adminFetch(`/admin/shop-maps/${versionId}/rollback`, {
  method: "POST", body: { requestId: requestId() },
});
export const deleteShopMap = (versionId) => adminFetch(`/admin/shop-maps/${versionId}`, {
  method: "DELETE", body: { requestId: requestId() },
});

export const createShopArea = (values) => adminFetch("/admin/shop-areas", {
  method: "POST",
  body: { requestId: requestId(), ...values },
});

export const updateShopArea = (areaId, values) => adminFetch(`/admin/shop-areas/${areaId}`, {
  method: "PATCH",
  body: { requestId: requestId(), ...values },
});

export const assignWarpArea = (warpId, areaId, warpCategory, reason, expectedUpdatedAt) =>
  adminFetch(`/admin/warp-zones/${warpId}/area`, {
    method: "PUT",
    body: { requestId: requestId(), areaId, warpCategory, reason, expectedUpdatedAt },
  });

export const reviewAreaCandidate = (candidateId, decision, reason, areaName) =>
  adminFetch(`/admin/shop-area-candidates/${candidateId}/${decision}`, {
    method: "POST",
    body: { requestId: requestId(), reason, ...(areaName ? { areaName } : {}) },
  });
